+
+        String pipelineId = "pipeline-inference-model-tracked";
+        putTrainedModelIngestPipeline(pipelineId, modelId);
+        createdPipelines.add(pipelineId);
+
+        // wait for the feature to start being used
+        assertBusy(() -> {
