+                        "        \"inference\": {\n" +
+                        "          \"inference_config\": {\"classification\":{}},\n" +
+                        "          \"model_id\": \"" + modelId + "\",\n" +
+                        "          \"field_map\": {}\n" +
+                        "        }\n" +
+                        "      }\n" +
+                        "    ]\n" +
+                        "  }"
+                ),
+                XContentType.JSON
+            )
+        ).actionGet();
+    }
