 POST /example/_doc
 {
   "location" : {
     "type" : "polygon",
-    "orientation" : "clockwise",
+    "orientation" : "LEFT",
     "coordinates" : [
-      [ [100.0, 0.0], [100.0, 1.0], [101.0, 1.0], [101.0, 0.0], [100.0, 0.0] ]
+      [ [-177.0, 10.0], [176.0, 15.0], [172.0, 0.0], [176.0, -15.0], [-177.0, -10.0], [-177.0, 10.0] ]
